def safe_copy():
    try:
        with open('source.txt', 'r') as src, open('backup.txt', 'w') as dst:
            for line in src:
                dst.write(line)
        success = True
    except FileNotFoundError:
        print('Source file not found.')
        success = False
    return success

def log_daily_sales(summary):
    try:
        with open('sales_log.txt', 'a') as f:
            f.write(summary + '\n')
        with open('sales_log.txt', 'r') as src, open('sales_log_backup.txt', 'w') as dst:
            dst.write(src.read())
        logged_and_backed_up = True
    except IOError:
        logged_and_backed_up = False
    return logged_and_backed_up

class SafeFileWriter:
    def __init__(self, path, mode):
        self.path = path
        self.mode = mode
        self.file = None
    def __enter__(self):
        self.file = open(self.path, self.mode)
        return self.file
    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.file:
            self.file.close()
        if exc_type is not None:
            print(f'Error during write: {exc_val}')
        return False

def generate_report():
    with SafeFileWriter('report.txt', 'w') as f:
        f.write('Quarterly Report\n')
